import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const WatchHeader = () => {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const isActive = (path) => location.pathname === path;

  const navLinks = [
    { name: 'Services', path: '/watch-services' },
    { name: 'Architecture', path: '/architecture' },
    { name: 'Case Studies', path: '/watch-case-study-health' },
    { name: 'Contact', path: '/watch-contact' },
  ];

  return (
    <header className='sticky top-0 z-50 border-b border-white/5 bg-background-dark/80 backdrop-blur-md'>
      <div className='max-w-[1280px] mx-auto px-6 md:px-10 h-20 flex items-center justify-between'>
        {/* Logo Area */}
        <Link className='flex items-center gap-3 hover:opacity-90 transition-opacity no-border-bottom' to='/watch-home'>
          <div className='size-10 bg-primary/10 flex items-center justify-center rounded-lg border border-primary/20 shadow-[0_0_15px_rgba(13,166,242,0.2)]'>
            <span className='material-symbols-outlined text-primary font-bold'>watch</span>
          </div>
          <h2 className='text-white text-lg font-bold tracking-tight hidden sm:block'>OfirYaron <span className='text-primary font-light'>Solutions</span></h2>
        </Link>

        {/* Desktop Navigation */}
        <nav className='hidden md:flex items-center gap-8'>
          {navLinks.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              className={`text-sm font-medium transition-colors no-border-bottom ${
                isActive(link.path) ? 'text-primary' : 'text-muted-slate hover:text-white'
              }`}
            >
              {link.name}
            </Link>
          ))}
        </nav>

        {/* CTA Button */}
        <div className='hidden md:flex items-center'>
          <Link
            className='bg-primary hover:bg-primary/90 text-white px-5 py-2.5 rounded-lg text-sm font-bold transition-all flex items-center gap-2 shadow-lg shadow-primary/10 hover:shadow-primary/30 no-border-bottom'
            to='/watch-contact'
          >
            <span>Book Consultation</span>
            <span className='material-symbols-outlined text-sm'>arrow_forward</span>
          </Link>
        </div>

        {/* Mobile Menu Toggle */}
        <button
          className='md:hidden text-white p-2'
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          aria-label={isMobileMenuOpen ? 'Close menu' : 'Open menu'}
          aria-expanded={isMobileMenuOpen}
          aria-controls='mobile-menu'
        >
          <span className='material-symbols-outlined'>{isMobileMenuOpen ? 'close' : 'menu'}</span>
        </button>
      </div>

      {/* Mobile Navigation Dropdown */}
      {isMobileMenuOpen && (
        <div id='mobile-menu' className='md:hidden absolute top-20 left-0 w-full bg-background-dark border-b border-white/5 p-6 flex flex-col gap-4 shadow-2xl'>
          {navLinks.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              className={`text-lg font-medium py-2 border-b border-white/5 no-border-bottom ${
                isActive(link.path) ? 'text-primary' : 'text-muted-slate'
              }`}
              onClick={() => setIsMobileMenuOpen(false)}
            >
              {link.name}
            </Link>
          ))}
          <Link
            className='bg-primary text-white py-3 rounded-lg text-center font-bold mt-4 no-border-bottom'
            to='/watch-contact'
            onClick={() => setIsMobileMenuOpen(false)}
          >
            Book Consultation
          </Link>
        </div>
      )}
    </header>
  );
};

export default WatchHeader;
